import{_ as t,c as a,o as n,a3 as s}from"./chunks/framework.Dokpd4od.js";const u=JSON.parse('{"title":"Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/index.md","filePath":"master/supply-chain/maintenance/index.md","lastUpdated":1792041590000}'),r={name:"master/supply-chain/maintenance/index.md"};function o(i,e,d,h,l,c){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="maintenance" tabindex="-1">Maintenance <a class="header-anchor" href="#maintenance" aria-label="Permalink to &quot;Maintenance&quot;">​</a></h1><p>Maintenance keeps your machines, vehicles and office devices working. You list each piece of equipment once. When something breaks, or when it needs regular care, you raise a maintenance request and give it to a team. The request moves through stages until the job is done.</p><blockquote><p><strong>In simple words:</strong> Maintenance answers three questions: what do we own, what is wrong with it, and who is fixing it.</p></blockquote><h2 id="the-whole-maintenance-flow" tabindex="-1">The whole maintenance flow <a class="header-anchor" href="#the-whole-maintenance-flow" aria-label="Permalink to &quot;The whole maintenance flow&quot;">​</a></h2><p>Every job follows the same path. Read it once, then use the tutorial to try it.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Set up  →  2. Add equipment  →  3. Report a problem  →  4. Assign and process  →  5. Close</span></span>
<span class="line"><span>                                                                  ↑                       |</span></span>
<span class="line"><span>                                                                  └── Preventive copy ←───┘</span></span></code></pre></div><ol><li><strong>Set up.</strong> Check the stages, create a maintenance team and an equipment category. See <a href="./setup/">Setup</a>.</li><li><strong>Add equipment.</strong> Record the machine with its category, team, technician, vendor and warranty. For example, <strong>Hydraulic Press 200T</strong>.</li><li><strong>Report a problem.</strong> Create a maintenance request, such as <strong>Hydraulic press oil leak</strong>, and pick the equipment.</li><li><strong>Assign and process.</strong> Set the team, the responsible person, a scheduled date and a duration. Open the request, click <strong>Edit</strong>, choose <strong>In Progress</strong> on the stage bar and click <strong>Save changes</strong>.</li><li><strong>Close.</strong> Choose <strong>Repaired</strong> and click <strong>Save changes</strong>. This stage is flagged as done, so the request counts as closed.</li></ol><p><strong>The preventive loop.</strong> Some work repeats, such as a monthly oil change. Create a <strong>Preventive</strong> request and tick <strong>Recurrent</strong>. When you save it in a done stage, Aureus opens the next copy for you, so the care never gets forgotten.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>New to the module? Follow <a href="./get-started/first-steps.html">First steps</a>. It takes you from an empty setup to a repaired machine in nine steps.</p></div><h2 id="menus" tabindex="-1">Menus <a class="header-anchor" href="#menus" aria-label="Permalink to &quot;Menus&quot;">​</a></h2><p>The top bar of the Maintenance app has three menus.</p><table tabindex="0"><thead><tr><th>Menu</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Maintenance</strong></td><td><strong>Maintenance Requests</strong> (the list of jobs) and <strong>Maintenance Calendar</strong> (jobs by scheduled date)</td></tr><tr><td><strong>Equipment</strong></td><td>Every machine or device you track, with vendor, serial number, cost and warranty</td></tr><tr><td><strong>Configurations</strong></td><td><strong>Stages</strong>, <strong>Teams</strong> and <strong>Categories</strong>, the building blocks of your setup</td></tr></tbody></table><h2 id="data-that-comes-ready-to-use" tabindex="-1">Data that comes ready to use <a class="header-anchor" href="#data-that-comes-ready-to-use" aria-label="Permalink to &quot;Data that comes ready to use&quot;">​</a></h2><p>A new installation includes this data, so you can start right away.</p><ul><li>One team: <strong>Internal Maintenance</strong>. New requests use it until you pick another team.</li><li>Four stages, in this order:</li></ul><table tabindex="0"><thead><tr><th>Stage</th><th>Done flag</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>New Request</strong></td><td>No</td><td>The problem is reported, nobody has started</td></tr><tr><td><strong>In Progress</strong></td><td>No</td><td>Someone is working on it</td></tr><tr><td><strong>Repaired</strong></td><td>Yes</td><td>The job is finished</td></tr><tr><td><strong>Scrap</strong></td><td>Yes</td><td>The equipment cannot be repaired</td></tr></tbody></table><p>You can rename, add or reorder stages later. See <a href="./setup/stages.html">Stages</a>.</p><h2 id="groups-in-this-guide" tabindex="-1">Groups in this guide <a class="header-anchor" href="#groups-in-this-guide" aria-label="Permalink to &quot;Groups in this guide&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>What you learn</th></tr></thead><tbody><tr><td><a href="./get-started/">Get started</a></td><td>A complete first tutorial, from setup to a repaired machine</td></tr><tr><td><a href="./setup/">Setup</a></td><td>Teams, equipment categories and stages</td></tr><tr><td><a href="./equipment/">Equipment</a></td><td>Add, find and archive equipment</td></tr><tr><td><a href="./requests/">Requests</a></td><td>Create, process and repeat maintenance jobs</td></tr><tr><td><a href="./calendar/maintenance-calendar.html">Calendar</a></td><td>Plan and review scheduled jobs by date</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./get-started/first-steps.html">First steps</a></li><li><a href="./setup/maintenance-teams.html">Maintenance teams</a></li><li><a href="./equipment/add-equipment.html">Add equipment</a></li><li><a href="./requests/create-request.html">Create a maintenance request</a></li><li><a href="./requests/preventive-maintenance.html">Preventive maintenance</a></li></ul>`,21)]))}const g=t(r,[["render",o]]);export{u as __pageData,g as default};
